   logic [D1_IDX_SIZE-1:0] addr1_s;
   logic [D2_IDX_SIZE-1:0] addr2_s;
   assign addr0_s = addr0;
   assign addr1_s = addr1;
   assign addr2_s = addr2;
   assign read_data = mem[addr0_s][addr1_s][addr2_s];
   always @(posedge clk) begin
