module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] TOTAL_PIXELS = 1024;
parameter [31:0] TOTAL_LINES = 512;
parameter [31:0] HSYNC_PULSE = 96;
parameter [31:0] HSYNC_BLANK = 48;
parameter [31:0] HSYNC_TOTAL = 128;
parameter [31:0] VSYNC_PULSE = 2;
parameter [31:0] VSYNC_BLANK = 10;
parameter [31:0] VSYNC_TOTAL = 32;
reg [9:0] h_counter;
reg [9:0] v_counter;
reg [9:0] h_counter_max;
reg [9:0] v_counter_max;
reg [9:0] h_counter_max_next;
reg [9:0] v_counter_max_next;
reg hsync;
reg vsync;
reg visible_region;
  always @(posedge pixel_clk) begin
    if(h_counter_max_next == 0) begin
      h_counter_max <= h_counter_max_next;
    end
    else begin
      h_counter_max <= h_counter_max_next;
    end
    if(v_counter_max_next == 0) begin
      v_counter_max <= v_counter_max_next;
    end
    else begin
      v_counter_max <= v_counter_max_next;
    end
    h_counter <= h_counter + 1;
    v_counter <= v_counter + 1;
    hsync <= h_counter < h_counter_max;
    vsync <= v_counter < v_counter_max;
    visible_region <= h_counter < h_counter_max && v_counter < v_counter_max;
  end
  always @(posedge pixel_clk) begin
    if(h_counter == h_counter_max) begin
      h_counter_max_next <= h_counter_max - HSYNC_BLANK;
    end
    else begin
      h_counter_max_next <= h_counter_max;
    end
    if(v_counter == v_counter_max) begin
      v_counter_max_next <= v_counter_max - VSYNC_BLANK;
    end
    else begin
      v_counter_max_next <= v_counter_max;
    end
  end
  assign pixel_x = h_counter;
  assign pixel_y = v_counter;
endmodule

