module add_1_bit(
input wire clk,
input wire x,
input wire y,
input wire cin,
output reg sum,
output reg cout
); 

always @(posedge clk) begin
    sum <= x ^ y ^ cin;
    cout <= (x & y) | (x & cin) | (y & cin);
  end
endmodule

