module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [2:0] ZERO = 3'b000;
    localparam [2:0] ONE = 3'b001;
    localparam [2:0] TWO = 3'b010;

    reg [2:0] state = ZERO;

    reg [N-1:0] data_p1 = {N{1'b0}};
    reg [N-1:0] data_p2 = {N{1'b0}};

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= {N{1'b0}};
            data_p2 <= {N{1'b0}};
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && s_ready) begin
                        state <= ONE;
                        data_p1 <= s_data;
                    end
                end
                ONE: begin
                    if (s_valid && s_ready) begin
                        state <= TWO;
                        data_p2 <= s_data;
                    end
                end
                TWO: begin
                    if (m_ready) begin
                        state <= ZERO;
                        m_data <= data_p2;
                        m_valid <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign s_ready = (state == ZERO) ? s_valid : 1'b0;
endmodule

