module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [31:0] reset_state = 3'b000;
parameter [31:0] idle_state = 3'b001;
parameter [31:0] running_state = 3'b010;
parameter [31:0] complete_state = 3'b011;
reg [2:0] current_state;
reg [2:0] next_state;
  always @(posedge clk) begin
    if((resetn == 1'b0)) begin
      current_state <= reset_state;
    end
    else begin
      current_state <= next_state;
    end
  end
  always @(*) begin
    case(current_state)
    reset_state : begin
      if((go == 1'b1)) begin
        next_state <= idle_state;
      end
      else begin
        next_state <= reset_state;
      end
    end
    idle_state : begin
      if((go == 1'b1)) begin
        next_state <= running_state;
      end
      else begin
        next_state <= idle_state;
      end
    end
    running_state : begin
      if((WREADY == 1'b1)) begin
        next_state <= complete_state;
      end
      else begin
        next_state <= running_state;
      end
    end
    complete_state : begin
      if((WREADY == 1'b0)) begin
        next_state <= running_state;
      end
      else begin
        next_state <= complete_state;
      end
    end
    default : begin
      next_state <= reset_state;
    end
    endcase
  end
  always @(posedge clk) begin
    if((resetn == 1'b0)) begin
      done <= 1'b0;
      WDATA <= 32'h0;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    else begin
      case(current_state)
      reset_state : begin
        done <= 1'b0;
        WDATA <= 32'h0;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
      end
      idle_state : begin
        done <= 1'b0;
        WDATA <= 32'h0;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
      end
      running_state : begin
        done <= 1'b0;
        WDATA <= data;
        WSTRB <= 4'hf;
        WVALID <= 1'b1;
      end
      complete_state : begin
        done <= 1'b1;
        WDATA <= 32'h0;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
      end
      default : begin
        done <= 1'b0;
        WDATA <= 32'h0;
        WSTRB <= 4'h0;
        WVALID <= 1'b0;
      end
      endcase
    end
  end
endmodule

