module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
parameter [1:0] IDLE = 2'b00,
              DATA0 = 2'b01,
              DATA1 = 2'b10;
  reg [1:0] state;
  reg [35:0] data0_o, data1_o;
  reg src0_rdy_o, src1_rdy_o;
  reg eof;
  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      src0_rdy_o <= 1'b0;
      src1_rdy_o <= 1'b0;
      data0_o <= 0;
      data1_o <= 0;
    end else if (clear) begin
      state <= IDLE;
      src0_rdy_o <= 1'b0;
      src1_rdy_o <= 1'b0;
      data0_o <= 0;
      data1_o <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
              state <= DATA0;
              src0_rdy_o <= 1'b1;
              src1_rdy_o <= 1'b0;
            end else begin
              state <= DATA1;
              src0_rdy_o <= 1'b0;
              src1_rdy_o <= 1'b1;
            end
          end
        end
        DATA0: begin
          if (dst0_rdy_i) begin
            state <= IDLE;
            src0_rdy_o <= 1'b0;
            src1_rdy_o <= 1'b0;
            data0_o <= data_i[35:0];
          end
        end
        DATA1: begin
          if (dst1_rdy_i) begin
            state <= IDLE;
            src0_rdy_o <= 1'b0;
            src1_rdy_o <= 1'b0;
            data1_o <= data_i[35:0];
          end
        end
      endcase
    end
  end
  assign dst_rdy_o = (state == DATA0) ? dst0_rdy_i : dst1_rdy_i;
  assign eof = data_i[35];
endmodule

