module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0;
reg [AW-1:0] cached_addr1;
reg [DW-1:0] cached_data0;
reg [DW-1:0] cached_data1;
reg [AW-1:0] subaddr;
reg good;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        good <= 1'b0;
    end else begin
        if (we) begin
            good <= 1'b1;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        addr_req <= {AW{1'b0}};
    end else begin
        if (addr_ok) begin
            addr_req <= {addr, {AW-DW{1'b0}}};
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        cached_addr0 <= {AW{1'b0}};
        cached_addr1 <= {AW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
    end else begin
        if (good) begin
            if (addr_req == cached_addr0) begin
                cached_data0 <= din;
            end
            if (addr_req == cached_addr1) begin
                cached_data1 <= din;
            end
        end
    end
end

assign subaddr = addr_req[AW-DW-1:0];

assign req = (addr_req != cached_addr0) || (addr_req != cached_addr1);

assign data_ok = good;

assign sdram_addr = addr_req + offset;

assign dout = (subaddr == 1'b0) ? cached_data0 : cached_data1;

endmodule

