module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  reg       io_ready;
  reg       tx;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
      io_ready <= 1'b0;
      tx <= 1'b0;
    end else begin
      case (state)
        4'b0000: begin
          if (io_valid) begin
            state <= 4'b0001;
            data <= io_bits;
          end else begin
            state <= 4'b0000;
          end
        end
        4'b0001: begin
          if (tick) begin
            state <= 4'b0010;
            tx <= data[0];
          end else begin
            state <= 4'b0001;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0010: begin
          if (tick) begin
            state <= 4'b0011;
            tx <= data[1];
          end else begin
            state <= 4'b0010;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0011: begin
          if (tick) begin
            state <= 4'b0100;
            tx <= data[2];
          end else begin
            state <= 4'b0011;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0100: begin
          if (tick) begin
            state <= 4'b0101;
            tx <= data[3];
          end else begin
            state <= 4'b0100;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0101: begin
          if (tick) begin
            state <= 4'b0110;
            tx <= data[4];
          end else begin
            state <= 4'b0101;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0110: begin
          if (tick) begin
            state <= 4'b0111;
            tx <= data[5];
          end else begin
            state <= 4'b0110;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b0111: begin
          if (tick) begin
            state <= 4'b1000;
            tx <= data[6];
          end else begin
            state <= 4'b0111;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b1000: begin
          if (tick) begin
            state <= 4'b1001;
            tx <= data[7];
          end else begin
            state <= 4'b1000;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b1001: begin
          if (tick) begin
            state <= 4'b1010;
            tx <= 1'b0;
          end else begin
            state <= 4'b1001;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b1010: begin
          if (tick) begin
            state <= 4'b1011;
            tx <= 1'b0;
          end else begin
            state <= 4'b1010;
            data <= {data[6:0], 1'b0};
          end
        end
        4'b1011: begin
          if (tick) begin
            state <= 4'b0000;
            io_ready <= 1'b1;
          end else begin
            state <= 4'b1011;
            data <= {data[6:0], 1'b0};
          end
        end
        default: begin
          state <= 4'b0000;
          io_ready <= 1'b0;
        end
      endcase
    end
  end
endmodule

