module mem_ctl(


    input wire clk,


    input wire [31:0]addr,

    input wire [31:0]data,


    input wire we,


    input wire [1:0]access_width
);
reg [31:0]data_to_write;

    always @(posedge clk) begin
        if(we) begin
            case(access_width)
                2'b00: data_to_write <= data[7:0];
                2'b01: data_to_write <= data[15:0];
                2'b10: data_to_write <= data[31:0];
            endcase
        end
    end

    assign $display("data_to_write: %h", data_to_write);
endmodule

module data_switch(
	sw_up_en,
	sw_down_en,
	db_down,
	db_up
);


input wire	sw_up_en;
input wire	sw_down_en;

inout wire	[7:0] db_down;

inout wire	[7:0] db_up;
assign db_up = sw_up_en ? db_down : 8'bzzzzzzzz;
assign db_down = sw_down_en ? db_up : 8'bzzzzzzzz;

endmodule

