module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] D_next;
reg [2:0] A_next;
reg WR_next;
reg RD_next;
reg [6:0] Y_next;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      D_next <= 3'b000;
      A_next <= 3'b000;
      WR_next <= 1'b0;
      RD_next <= 1'b0;
    end else begin
      D_next <= D;
      A_next <= A;
      WR_next <= WR;
      RD_next <= RD;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      Y_next <= 7'b0000000;
    end else begin
      Y_next <= Y;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      WCTRL <= 1'b0;
    end else begin
      WCTRL <= WR_next;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      Y <= 7'b0000000;
    end else begin
      Y <= Y_next;
