module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
); 

parameter CLK_SPEED = 100000000;
parameter timeout_const = 100000000 / 1000000;
parameter debounce_const = 100000000 / 1000000;
reg [7:0] shift_reg;
reg clk_filter;
reg [31:0] bitsCount;
reg [31:0] timeout;
reg [31:0] debounce;
  always @(posedge clk) begin
    if((bitsCount == 0)) begin
      shift_reg <= 8'h00;
      clk_filter <= 1'b0;
      timeout <= 0;
      debounce <= 0;
    end
    else begin
      if((clk_filter == 1'b0)) begin
        shift_reg <= {shift_reg[6:0], kbd_dat};
        clk_filter <= 1'b1;
        timeout <= timeout_const;
        debounce <= debounce_const;
      end
      else begin
        if((timeout == 0)) begin
          clk_filter <= 1'b0;
          timeout <= 0;
          debounce <= debounce_const;
        end
        else begin
          timeout <= timeout - 1;
          debounce <= debounce - 1;
        end
      end
    end
  end
  always @(posedge clk) begin
    if((bitsCount == 0)) begin
      interrupt <= 1'b0;
      scanCode <= 8'h00;
    end
    else begin
      if((bitsCount == 8)) begin
        interrupt <= 1'b1;
        scanCode <= shift_reg;
      end
      else begin
        interrupt <= 1'b0;
        scanCode <= 8'h00;
      end
    end
  end
  always @(posedge clk) begin
    if((bitsCount == 0)) begin
      bitsCount <= 0;
    end
    else begin
      if((bitsCount == 8)) begin
        bitsCount <= 0;
      end
      else begin
        bitsCount <= bitsCount + 1;
      end
    end
  end
endmodule

