module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE = 1280;
parameter [31:0] H_FRONT_PORCH = 16;
parameter [31:0] H_BACK_PORCH = 48;
parameter [31:0] H_SYNC_PULSE = 96;
parameter [31:0] H_TOTAL = 1280 + 16 + 48 + 96;
parameter [31:0] V_ACTIVE = 720;
parameter [31:0] V_FRONT_PORCH = 10;
parameter [31:0] V_BACK_PORCH = 23;
parameter [31:0] V_SYNC_PULSE = 2;
parameter [31:0] V_TOTAL = 720 + 10 + 23 + 2;
reg [10:0] X;
reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      X <= 11'b0000000000;
      Y <= 11'b0000000000;
      H_SYNC <= 1'b1;
      V_SYNC <= 1'b1;
      DISP_EN <= 1'b0;
    end else begin
      if((X == H_TOTAL - 1)) begin
        X <= 11'b0000000000;
        Y <= Y + 1;
      end else begin
        X <= X + 1;
      end
      if((Y == V_TOTAL - 1)) begin
        Y <= 11'b0000000000;
      end
      if((X == H_ACTIVE - 1)) begin
        H_SYNC <= 1'b0;
      end
      if((X == H_ACTIVE + H_FRONT_PORCH)) begin
        H_SYNC <= 1'b1;
      end
      if((X == H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE)) begin
        H_SYNC <= 1'b0;
      end
      if((Y == V_ACTIVE - 1)) begin
        V_SYNC <= 1'b0;
      end
      if((Y == V_ACTIVE + V_FRONT_PORCH)) begin
        V_SYNC <= 1'b1;
      end
      if((Y == V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE)) begin
        V_SYNC <= 1'b0;
      end
      if((Y == V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH)) begin
        DISP_EN <= 1'b1;
      end
      if((Y == V_TOTAL - 1)) begin
        DISP_EN <= 1'b0;
      end
    end
  end
endmodule

