module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
reg [3:0] counter;
reg [3:0] parity;
reg [3:0] stop;
reg scan_ready;

always @(posedge i_clock or posedge reset) begin
    if (reset) begin
        scan_code <= 8'b0;
        counter <= 4'b0;
        parity <= 4'b0;
        stop <= 4'b0;
        scan_ready <= 1'b0;
    end else begin
        if (i_clock == 1'b0) begin
            if (counter == 4'b0000) begin
                scan_code <= 8'b0;
                counter <= 4'b0001;
                parity <= 4'b0000;
                stop <= 4'b0000;
                scan_ready <= 1'b0;
            end else if (counter == 4'b0001) begin
                scan_code <= {scan_code[6:0], i_data};
                counter <= 4'b0010;
            end else if (counter == 4'b0010) begin
                scan_code <= {scan_code[6:0], i_data};
                counter <= 4'b0011;
            end else if (counter == 4'b0011) begin
                scan_code <= {scan_code[6:0], i_data};
                counter <= 4'b0100;
            end else if (counter == 4'b0100) begin
                scan_code <= {scan_code[6:0], i_data};
                counter <= 4'b0101;
            end else if (counter == 4'b0101) begin
                scan_code <= {scan_code[6:0], i_data};
