module CLG4_3(x1, y1, x2, y2, x3, y3, x4, y4, c1,
            s1, s2, s3, s4);
input x1, y1, x2, y2, x3, y3, x4, y4, c1;
output s1, s2, s3, s4;
wire p1, p2, p3, p4, g1, g2, g3, g4, c2, c3, c4;
assign p1 = x1 ^ y1;
assign p2 = x2 ^ y2;
assign p3 = x3 ^ y3;
assign p4 = x4 ^ y4;
assign g1 = x1 & y1;
assign g2 = x2 & y2;
assign g3 = x3 & y3;
assign g4 = x4 & y4;
assign c2 = g1 | (g2 & c1);
assign c3 = g3 | (g4 & c2);
assign c4 = g4 | (c3 & c1);
assign s1 = c1 ^ p1;
assign s2 = c2 ^ p2;
assign s3 = c3 ^ p3;
assign s4 = c4 ^ p4;
endmodule

module fir_filter_slice #(
  parameter IN_WIDTH     = 16,
  parameter COEFF_WIDTH  = 16,
  parameter ACCUM_WIDTH  = 32,
  parameter OUT_WIDTH    = 32)
(
  input clk,
  input reset,
  input clear,
  input sample_in_stb,
  input signed [IN_WIDTH-1:0] sample_in_a,       
  input signed [IN_WIDTH-1:0] sample_in_b,       
  output signed [IN_WIDTH-1:0] sample_forward,   
  input signed [COEFF_WIDTH-1:0] coeff_in,       
  output signed [COEFF_WIDTH-1:0] coeff_forward, 
  input coeff_load_stb,                          
  input signed [ACCUM_WIDTH-1:0] sample_accum,   
  output signed [OUT_WIDTH-1:0] sample_out       
);
reg [IN_WIDTH-1:0] a_reg;
  reg [IN_WIDTH-1:0] b_reg;
  reg [ACCUM_WIDTH-1:0] ad_reg;
  reg [COEFF_WIDTH-1:0] m_reg;
  reg [ACCUM_WIDTH-1:0] p_reg;

  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end else if (sample_in_stb) begin
      a_reg <= sample_in_a;
      b_reg <= sample_in_b;
      ad_reg <= a_reg + b_reg;
    end else if (coeff_load_stb) begin
      m_reg <= coeff_in;
    end else begin
      ad_reg <= ad_reg;
      m_reg <= m_reg;
    end
  end

  assign sample_forward = ad_reg;
  assign coeff_forward = m_reg;

  always @(posedge clk) begin
    if (reset) begin
      p_reg <= 0;
    end else if (clear) begin
      p_reg <= 0;
    end else begin
      p_reg <= p_reg + ad_reg * m_reg;
    end
  end

  assign sample_out = p_reg[OUT_WIDTH-1:0];

endmodule

