module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);
wire signed	[Q_WIDTH-1:0]		r_q_P[LATENCY];
wire signed	[Q_WIDTH-1:0]		r_a_1P;
wire signed	[Q_WIDTH-1:0]		r_b_1P;

assign r_a_1P = a;
assign r_b_1P = b;

always @(posedge clk or posedge arst)
begin
	if (arst == 1'b1)
	begin
		r_q_P[0] <= 0;
	end
	else
	begin
		r_q_P[0] <= r_a_1P * r_b_1P;
	end
end

genvar i;
generate
	if (LATENCY == 1)
	begin
		assign o = r_q_P[0];
	end
	else
	begin
		for (i = 1; i < LATENCY; i = i + 1)
		begin
			assign r_q_P[i] = r_q_P[i-1];
		end
		assign o = r_q_P[LATENCY-1];
	end
endgenerate

endmodule

