module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    ZERO = 3'b000,
    ONE  = 3'b001,
    TWO  = 3'b010;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [2:0]   state;

assign m_data = data_p1;
assign m_valid = (state == TWO) ? 1'b1 : 1'b0;
assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
    end else begin
        case (state)
            ZERO: begin
                if (s_valid) begin
                    state <= ONE;
                    data_p1 <= s_data;
                end
            end
            ONE: begin
                if (m_ready) begin
                    state <= TWO;
                    data_p2 <= data_p1;
                end
            end
            TWO: begin
                if (s_valid) begin
                    state <= ONE;
                    data_p1 <= s_data;
                end
            end
        endcase
    end
end

assign data_p1 = (state == TWO) ? data_p2 : data_p1;

endmodule

