module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [3:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            dout_parallel <= 0;
            dout_valid <= 0;
        end else begin
            if (din_valid) begin
                dout_parallel <= {dout_parallel[6:0], din_serial};
                counter <= counter + 1;
                if (counter == 8) begin
                    dout_valid <= 1;
                    counter <= 0;
                end
            end
        end
    end
endmodule

