module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );
reg [63:0] a0,a1,b0,b1,b2,b3,c0,c1,d0,d1,d2,d3;
    always @* begin
        a0 = a + m0;
        a1 = a0 ^ m1;
        b0 = b + a1;
        b1 = b0 >> 32;
        b2 = b0 << 32;
        b3 = b2 ^ a1;
        c0 = c + b3;
        c1 = c0 >> 32;
        c2 = c0 << 32;
        c3 = c2 ^ b3;
        d0 = d + c3;
        d1 = d0 >> 32;
        d2 = d0 << 32;
        d3 = d2 ^ c3;
        a_prim = d3;
        b_prim = d0;
        c_prim = d1;
        d_prim = d2;
