module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg synch = 1'b0;
    reg [1:0] counter = 2'b00;
    always @(posedge clk) begin
        if (toggle_en) begin
            if (counter == cnt_n) begin
                counter <= cnt_m;
                synch <= 1'b1;
            end
            else if (counter == cnt_m) begin
                counter <= cnt_n;
                synch <= 1'b0;
            end
            else begin
                counter <= counter + 1;
            end
        end
        if (opMode) begin
            synchroStatus <= synch;
            syncInOut <= synch;
        end
        else begin
            synchroStatus <= synchroStatus;
            syncInOut <= synchroStatus;
        end
    end
endmodule

