	if(islow == 1) begin
		carry_out = 0;
		regcarry = carry_in;
	end
	else begin
		carry_out = regcarry;
	end
	if(islow == 1) begin
		led2 = 0;
	end
	else begin
		if(sign == 3'b001) begin
			led2 = carry_out;
		end
		else if(sign == 3'b010) begin
			led2 = ~carry_out;
		end
		else if(sign == 3'b011) begin
			led2 = carry_out;
		end
		else if(sign == 3'b100) begin
			led2 = ~carry_out;
		end
		else if(sign == 3'b101) begin
			led2 = carry_out;
		end
		else if(sign == 3'b110) begin
			led2 = ~carry_out;
		end
		else if(sign == 3'b111) begin
			led2 = carry_out;
		end
	end
end
endmodule

