module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    reg[31:0] x_var_temp; 
    reg[31:0] y_var_temp; 
    reg[31:0] u_var_temp; 
    reg[31:0] Xoutport; 
    reg[31:0] Youtport; 
    reg[31:0] Uoutport; 
    always @(posedge CLK or posedge reset) begin
        if (reset == 1) begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
            Xoutport <= 0; 
            Youtport <= 0; 
            Uoutport <= 0; 
        end
        else begin
            x_var_temp <= x_var + DXport; 
            y_var_temp <= y_var + DXport * u_var; 
            u_var_temp <= u_var + DXport * (Xinport - y_var); 
            if (x_var_temp >= Aport) begin
                x_var <= x_var_temp; 
                y_var <= y_var_temp; 
                u_var <= u_var_temp; 
                Xoutport <= x_var; 
                Youtport <= y_var; 
                Uoutport <= u_var; 
            end
            else begin
                x_var <= x_var_temp; 
                y_var <= y_var_temp; 
                u_var <= u_var_temp; 
            end
        end
    end
endmodule

