module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    generate
        for (genvar i = 0; i < BITS; i = i + 1) begin : gen
            assign enable_wires[i] = ena;
            always @(posedge clk or posedge rst) begin
                if (rst) begin
                    cnt[i] <= 1'b0;
                end else if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1'b1;
                    end else begin
                        cnt[i] <= cnt[i] - 1'b1;
                    end
                end
            end
        end
    endgenerate
    assign out = cnt;
    assign ovf = (cnt[BITS - 1] == 1'b1 && updown) || (cnt[BITS - 1] == 1'b0 && !updown);
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] r;
		assign r = binary;
		assign b = r[3:0];
		assign s = r[7:4];
		assign g = r[11:8];
		assign q = r[15:12];
		always @ (r)
		begin
			for (int i = 0; i < 16; i = i + 1)
			begin
				if (r[4*i + 3] == 1)
				begin
					r[4*i + 3] = 0;
					r[4*i + 2] = r[4*i + 2] + 1;
				end
				if (r[4*i + 2] == 1)
				begin
					r[4*i + 2] = 0;
					r[4*i + 1] = r[4*i + 1] + 1;
				end
				if (r[4*i + 1] == 1)
				begin
					r[4*i + 1] = 0;
					r[4*i + 0] = r[4*i + 0] + 1;
				end
				if (r[4*i + 0] == 1)
				begin
					r[4*i + 0] = 0;
					r[4*i + 3] = r[4*i + 3] + 1;
				end
			end
			r = r >> 4;
		end
endmodule

