module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg [15:0] bm_tag;
reg bm_done;
reg [15:0] op_tag;
reg op_done;
  always @(posedge CLK, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rd_compl_tag <= {16{1'b0}};
      rd_compl_start <= 1'b0;
      rd_compl_done <= 1'b0;
      bm_tag <= {16{1'b0}};
      bm_done <= 1'b0;
      op_tag <= {16{1'b0}};
      op_done <= 1'b0;
    end else begin
      rd_compl_tag <= RD_COMPL_TAG;
      rd_compl_start <= RD_COMPL_START;
      rd_compl_done <= RD_COMPL_DONE;
      bm_tag <= BM_TAG;
      bm_done <= BM_DONE;
      op_tag <= rd_compl_start ? rd_compl_tag : bm_done ? bm_tag : {16{1'b0}};
      op_done <= rd_compl_done || bm_done;
    end
  end
  assign OP_TAG = op_tag;
  assign OP_DONE = op_done;
endmodule

