module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFileMem [31:0];
    always @ (negedge Clk) begin
        if (ReadReg1 != 0) ReadData1 <= RegFileMem[ReadReg1];
        if (ReadReg2 != 0) ReadData2 <= RegFileMem[ReadReg2];
    end
    always @ (posedge Clk) begin
        if (RegWrite) RegFileMem[WriteReg] <= WriteData;
    end
endmodule

module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 5.0;
    parameter C_L = 1.0;
    parameter t_hmin = 0.0;
    parameter t_hmax = 0.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR == 1'b0) begin
            Q <= 1'b0;
        end
        else begin
            Q <= D;
        end
    end
    always @(Q) begin
        if (Q == 1'b1) begin
            counter = counter + 1;
        end
        else begin
            counter = counter - 1;
        end
    end
    always @(posedge CLK) begin
        $display("Power dissipation: %d", counter * C_L * Vcc^2);
    end
endmodule

