module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem[0:DEPTH-1];
    reg [DEPTH_BITS-1:0] index;
    reg empty, full;
    assign empty_n = ~empty;
    assign full_n = ~full;
    always @(posedge clk) begin
        if (aclr) begin
            empty <= 1'b1;
            full <= 1'b0;
            index <= 0;
        end else begin
            if (write && !full) begin
                mem[index] <= din;
                index <= index + 1;
                if (index == DEPTH - 1) begin
                    full <= 1'b1;
                end
                empty <= 1'b0;
            end
            if (read && !empty) begin
                index <= index - 1;
                if (index == 0) begin
                    empty <= 1'b1;
                end
                full <= 1'b0;
            end
        end
    end
    assign dout = mem[index];
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
  if(timer < 1000000) begin
    timer <= timer + 1;
  end
  else begin
    if(btn_input == pre) begin
      btn_output <= btn_input;
      timer <= 0;
      pre <= btn_input;
    end
  end
end
endmodule

