module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter [31:0] N=4;
parameter [31:0] SIZE=N+1;
parameter [31:0] Zeros=0;

reg [SIZE-1:0] state;
reg [SIZE-1:0] toggle;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		state <= {Zeros, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0};
	end
	else if (enable) begin
		state[SIZE-1] <= 1'b0;
		state[SIZE-2] <= ~state[SIZE-2];
		state[SIZE-3] <= ~state[SIZE-3];
		state[SIZE-4] <= ~state[SIZE-4];
		state[SIZE-5] <= ~state[SIZE-5];
		state[SIZE-6] <= ~state[SIZE-6];
		state[SIZE-7] <= ~state[SIZE-7];
		state[SIZE-8] <= ~state[SIZE-8];
	end
end

always @(state) begin
	toggle[0] <= 1'b1;
	toggle[1] <= state[SIZE-2] ^ state[SIZE-3];
	toggle[2] <= state[SIZE-3] ^ state[SIZE-4];
	toggle[3] <= state[SIZE-4] ^ state[SIZE-5];
	toggle[4] <= state[SIZE-5] ^ state[SIZE-6];
	toggle[5] <= state[SIZE-6] ^ state[SIZE-7];
	toggle[6] <= state[SIZE-7] ^ state[SIZE-8];
	toggle[7] <= state[SIZE-8] ^ state[SIZE-9];
end

assign gray_out = state[SIZE-1:1];

endmodule

