module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0]fib1;
    reg [7:0]fib2;
    reg [7:0]fib3;
    always @(posedge CLK_IN) begin
        if(RST_N == 1'b0) begin
            fib1 <= 8'b00000000;
            fib2 <= 8'b00000000;
            fib3 <= 8'b00000000;
        end
        else begin
            fib1 <= fib2;
            fib2 <= fib3;
            fib3 <= fib1 + fib2;
        end
    end
    assign SEQUENCE = fib3;
endmodule

