module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 1;

 reg [DATA_WIDTH-1:0] r_dataout;
 reg r_dataout_valid;
 reg r_dataout_stall;

 always @ (posedge clock or negedge resetn)
   if (!resetn)
     begin
       r_dataout <= {DATA_WIDTH{1'b0}};
       r_dataout_valid <= 1'b0;
       r_dataout_stall <= 1'b0;
     end
   else
     begin
       r_dataout <= o_dataout;
       r_dataout_valid <= o_dataout_valid;
       r_dataout_stall <= o_datain_stall;
     end

 assign o_datain_stall = r_dataout_stall;
 assign o_dataout = r_dataout;
 assign o_dataout_valid = r_dataout_valid;

 if (INSERT_REGISTER == 1)
   begin
     always @ (posedge clock or negedge resetn)
       if (!resetn)
         begin
           o_dataout <= {DATA_WIDTH{1'b0}};
           o_dataout_valid <= 1'b0;
           o_datain_stall <= 1'b0;
         end
       else
         begin
           o_dataout <= i_datain;
           o_dataout_valid <= i_datain_valid;
           o_datain_stall <= i_dataout_stall;
         end
   end
 else
   begin
     assign o_dataout = i_datain;
     assign o_dataout_valid = i_datain_valid;
     assign o_datain_stall = i_dataout_stall;
   end

endmodule

