module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			data_reg <= 0;
			data_regnum <= 0;
		end
		else begin
			if(data_in_sign) begin
				data_reg <= data_reg + data_in;
			end
			else begin
				data_reg <= data_reg;
			end
			if(data_valid) begin
				data_regnum <= data_regnum + 1;
			end
			else begin
				data_regnum <= data_regnum;
			end
		end
	end

	assign data_out = data_valid ? data_reg : 0;
	assign data_out_sign = data_valid;
	assign data_ok = data_valid ? (data_reg == 28 || data_reg == 36) : 0;
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks;
reg clk_out;
  always @(posedge clk_100MHz, posedge reset) begin
    if((reset == 1'b1)) begin
      ticks <= 32'd499999;
      clk_out <= 1'b0;
    end else begin
      if((ticks == 32'd0)) begin
        clk_out <= ~clk_out;
        ticks <= 32'd499999;
      end
      else begin
        ticks <= ticks - 1;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

