module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter		Divider = 100000;
reg [26:0]	Counter;
always @(posedge Clock) begin
	if (MR) begin
		Counter <= 0;
		Timeout <= 0;
	end
	else if (Counter == Divider) begin
		Timeout <= 1;
		Counter <= 0;
	end
	else begin
		Timeout <= 0;
		Counter <= Counter + 1;
	end
end
always @(posedge Clock) begin
	if (MR) begin
		Counter <= 0;
	end
	else if (Counter == Divider) begin
		Counter <= 0;
	end
	else if (Counter > Divider) begin
		Counter <= 0;
	end
	else begin
		Counter <= Counter + 1;
	end
end
endmodule

