                TWO: begin
                    if (s_valid && s_ready && m_ready) begin
                        state <= ZERO;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            case (state)
                ZERO: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
                ONE: begin
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
