always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        cnt_val <= 0;
        run <= 0;
        done <= 0;
    end else begin
        state <= state_n;
        cnt_val <= cnt_val_n;
        run <= run_o;
        done <= done_o;
    end
end

