                state_n = 2'b01;
                cnt_val_n = cnt_val_i;
            end
        end
        2'b01: begin
            if (cnt_val == cnt_i) begin
                state_n = 2'b10;
                run = 1;
            end
        end
        2'b10: begin
            done = 1;
            state_n = 2'b00;
        end
        default: begin
            state_n = 2'b00;
        end
    endcase
end

