            2'b11: Y_reg <= D3;
        endcase
        if (EN_n == 1'b0) Y_reg <= 1'b0;
    end
endmodule

module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

parameter [31:0] f_incr = 32'h00000000;
reg [31:0] len_raw;
reg [31:0] len;
reg [31:0] x_mask;
reg [31:0] f_masked;
reg [31:0] incr;
reg [31:0] f_out;
reg [31:0] res;
  always @(posedge clk) begin
    len_raw <= f[30:23] - 255;
    if(len_raw[0] == 1'b1) begin
      len <= 32'h00000001;
    end
    else begin
      len <= 32'h00000000;
    end
  end
  always @(posedge clk) begin
    x_mask <= f[30:23] >> len;
  end
  always @(posedge clk) begin
    f_masked <= f & ~x_mask;
  end
  always @(posedge clk) begin
    incr <= f_masked;
    incr[31:0] <= incr[31:0] + 1;
  end
  always @(posedge clk) begin
    f_out <= f_masked;
    f_out[31:0] <= f_incr;
    f_out[31:0] <= f_out[31:0] & ~x_mask;
  end
  always @(posedge clk) begin
    res <= f;
    res[31:0] <= f_out[31:0];
    res[31:0] <= res[31:0] << len;
    res[31:0] <= res[31:0] | f[22:0];
    if(res[31] == 1'b1) begin
      res[31:0] <= res[31:0] | 32'h80000000;
    end
  end
  always @(posedge clk) begin
    g <= res;
  end
endmodule

