module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
    );
reg [2:0] step_count = 0;
    always @(posedge sysclk) begin
        if (anodes != 8'b00000000) begin
            if (step_count == 0) begin
                shift <= 1'b1;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b010) begin
                shift <= 1'b0;
                latch <= 1'b1;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b011) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b100) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b101) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b110) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b111) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else if (step_count == 3'b000) begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
            else begin
                shift <= 1'b0;
                latch <= 1'b0;
                step_count <= 3'b001;
            end
        end
        else begin
            shift <= 1'b0;
            latch <= 1'b0;
            step_count <= 3'b000;
        end
        if (step_count == 3'b001) begin
            data <= anodes[0];
            step_count <= 3'b000;
        end
        else if (step_count == 3'b000) begin
            data <= anodes[1];
            step_count <= 3'b001;
        end
        else if (step_count == 3'b011) begin
            data <= anodes[2];
            step_count <= 3'b010;
        end
        else if (step_count == 3'b010) begin
            data <= anodes[3];
            step_count <= 3'b011;
        end
        else if (step_count == 3'b101) begin
            data <= anodes[4];
            step_count <= 3'b100;
        end
        else if (step_count == 3'b100) begin
            data <= anodes[5];
            step_count <= 3'b101;
        end
        else if (step_count == 3'b111) begin
            data <= anodes[6];
            step_count <= 3'b110;
        end
        else if (step_count == 3'b110) begin
            data <= anodes[7];
            step_count <= 3'b111;
        end
    end
endmodule

