module Administrador_de_salidas(
    input [2:0] RY,
    input [7:0] RX,
    input [2:0] Num,
    input [1:0] Sel_Salidas,
    output reg [7:0] o_Dataout,
    output reg [7:0] o_Addressdata,
    output reg ReadWrite
);
always@* begin
        case(Sel_Salidas)
            2'b00: begin
                o_Dataout = 8'b0;
                o_Addressdata = 8'b0;
                ReadWrite = 1'b0;
            end
            2'b01: begin
                o_Dataout = 8'b0;
                o_Addressdata = RY[2:0];
                ReadWrite = 1'b0;
            end
            2'b10: begin
                o_Dataout = Num[2:0];
                o_Addressdata = RX;
                ReadWrite = 1'b1;
            end
            2'b11: begin
                o_Dataout = RX;
                o_Addressdata = RY;
                ReadWrite = 1'b0;
            end
            default: begin
                o_Dataout = 8'b0;
                o_Addressdata = 8'b0;
                ReadWrite = 1'b0;
            end
        endcase
    end
endmodule

module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;
    reg [1:0] state;
    reg [1:0] next;
    reg s_ready_t;

    assign s_ready = s_ready_t;
    assign m_data = data_p1;
    assign m_valid = load_p1;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
            s_ready_t <= 1'b0;
        end else begin
            state <= next;
            load_p1 <= load_p1_from_p2;
            load_p2 <= load_p2;
            load_p1_from_p2 <= 1'b0;
            s_ready_t <= 1'b0;
        end
    end

    always @(*) begin
        case (state)
            2'b00: begin
                if (s_valid && m_ready) begin
                    next = 2'b01;
                end else begin
                    next = 2'b00;
                end
            end
            2'b01: begin
                if (s_valid && m_ready) begin
                    next = 2'b10;
                end else begin
                    next = 2'b01;
                end
            end
            2'b10: begin
                if (s_valid && m_ready) begin
                    next = 2'b00;
                end else begin
                    next = 2'b10;
                end
            end
            default: begin
                next = 2'b00;
            end
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            data_p1 <= {N{1'b0}};
            data_p2 <= {N{1'b0}};
        end else begin
            if (load_p1) begin
                data_p1 <= s_data;
            end
            if (load_p2) begin
                data_p2 <= s_data;
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            if (state == 2'b00 && s_valid && m_ready) begin
                load_p1 <= 1'b1;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b0;
            end
            if (state == 2'b01 && s_valid && m_ready) begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b1;
                load_p1_from_p2 <= 1'b0;
            end
            if (state == 2'b10 && s_valid && m_ready) begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b1;
            end
        end
    end

endmodule

