        if(wrreq && !full)
        begin
            mem[wrptr] <= data_in;
            wrptr <= wrptr + 1;
            usedw <= usedw + 1;
            empty <= 0;
            full <= 0;
        end
        if(rdreq && !empty)
        begin
            data_out <= mem[rdptr];
            rdptr <= rdptr + 1;
            usedw <= usedw - 1;
            empty <= 0;
            full <= 0;
        end
        if(empty)
        begin
            usedw <= 0;
            full <= 0;
        end
        if(full)
        begin
            usedw <= FIFO_DEPTH-1;
            empty <= 0;
        end
    end
end

endmodule

