module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg [2:0] SyncA_clkB;
reg clkA_data, clkB_data;
reg FlagToggle_clkA;
assign FlagOut_clkB = SyncA_clkB[2];
always @(posedge clkA) begin
    if (FlagIn_clkA) begin
        clkA_data <= dataA;
        FlagToggle_clkA <= ~FlagIn_clkA;
    end
end
always @(posedge clkB) begin
    if (FlagToggle_clkA) begin
        SyncA_clkB <= {SyncA_clkB[1:0], FlagIn_clkA};
        clkB_data <= clkA_data;
    end
end
assign dataB = clkB_data;
endmodule

module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
); 

wire D_d1;
wire D_d2;
wire D_d4;
wire D_d8;
wire D_d16;
wire Q_d1;
wire Q_d2;
wire Q_d4;
wire Q_d8;
wire Q_d16;
  gh_delay #(
    .DELAY(1'b0)) D_d1_inst(
    .CLK(CLK),
    .D(D),
    .Q(D_d1));
  gh_delay #(
    .DELAY(2'b01)) D_d2_inst(
    .CLK(CLK),
    .D(D_d1),
    .Q(D_d2));
  gh_delay #(
    .DELAY(2'b10)) D_d4_inst(
    .CLK(CLK),
    .D(D_d2),
    .Q(D_d4));
  gh_delay #(
    .DELAY(2'b11)) D_d8_inst(
    .CLK(CLK),
    .D(D_d4),
    .Q(D_d8));
  gh_delay #(
    .DELAY(3'b001)) D_d16_inst(
    .CLK(CLK),
    .D(D_d8),
    .Q(D_d16));
  gh_delay #(
    .DELAY(1'b0)) Q_d1_inst(
    .CLK(CLK),
    .D(D),
    .Q(Q_d1));
  gh_delay #(
    .DELAY(2'b01)) Q_d2_inst(
    .CLK(CLK),
    .D(D_d1),
    .Q(Q_d2));
  gh_delay #(
    .DELAY(2'b10)) Q_d4_inst(
    .CLK(CLK),
    .D(D_d2),
    .Q(Q_d4));
  gh_delay #(
    .DELAY(2'b11)) Q_d8_inst(
    .CLK(CLK),
    .D(D_d4),
    .Q(Q_d8));
  gh_delay #(
    .DELAY(3'b001)) Q_d16_inst(
    .CLK(CLK),
    .D(D_d8),
    .Q(Q_d16));
  assign Q = DELAY[0] ? D : DELAY[1] ? D_d2 : DELAY[2] ? D_d4 : DELAY[3] ? D_d8 : DELAY[4] ? D_d16 : Q_d1;
endmodule

module mulor_3_stage_signed_10_bit(
