  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_x_q, M_y_q, M_z_q, M_w_q, M_w_d;

  assign M_w_d = {1'b0, seed};

  always @(posedge clk) begin
    if (rst) begin
      M_x <= M_w_d;
      M_y <= M_w_d;
      M_z <= M_w_d;
      M_w <= M_w_d;
    end else begin
      M_x <= M_x_q;
      M_y <= M_y_q;
      M_z <= M_z_q;
      M_w <= M_w_q;
    end
  end

  assign M_x_q = M_x;
  assign M_y_q = M_y;
  assign M_z_q = M_z;
  assign M_w_q = M_w;

  assign num = M_w_q;

  localparam T = 32'h12345678;

  always @(posedge clk) begin
    if (rst) begin
      M_x <= M_w_d;
      M_y <= M_w_d;
      M_z <= M_w_d;
      M_w <= M_w_d;
    end else begin
      M_x <= M_x_q;
      M_y <= M_y_q;
      M_z <= M_z_q;
      M_w <= M_w_q;
      M_w <= M_w_q ^ M_x_q ^ M_y_q ^ M_z_q ^ T;
    end
  end

endmodule

