module adder_word(	input wire [31:0] a,
			input wire [31:0] b,
			input wire carry_in,
			output wire [31:0] sum,
			output wire carry_out);
wire [7:0] tmp_carry;
	assign tmp_carry[0] = carry_in;
	assign sum[7:0] = a[7:0] + b[7:0] + tmp_carry[0];
	assign sum[15:8] = a[15:8] + b[15:8] + tmp_carry[1];
	assign sum[23:16] = a[23:16] + b[23:16] + tmp_carry[2];
	assign sum[31:24] = a[31:24] + b[31:24] + tmp_carry[3];
	assign carry_out = tmp_carry[3];
endmodule

