module gh_delay_programmable_63(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [5:0] DELAY,
output wire Q
); 

wire Q_d1;
  wire Q_d2;
  wire Q_d4;
  wire Q_d8;
  wire Q_d16;
  wire Q_d32;
  gh_delay #(
    .DELAY(2'h0)) 
  inst_0(
    .CLK(CLK),
    .D(D),
    .Q(Q_d1));
  gh_delay #(
    .DELAY(2'h1)) 
  inst_1(
    .CLK(CLK),
    .D(D),
    .Q(Q_d2));
  gh_delay #(
    .DELAY(2'h2)) 
  inst_2(
    .CLK(CLK),
    .D(D),
    .Q(Q_d4));
  gh_delay #(
    .DELAY(2'h3)) 
  inst_3(
    .CLK(CLK),
    .D(D),
    .Q(Q_d8));
  gh_delay #(
    .DELAY(2'h4)) 
  inst_4(
    .CLK(CLK),
    .D(D),
    .Q(Q_d16));
  gh_delay #(
    .DELAY(2'h5)) 
  inst_5(
    .CLK(CLK),
    .D(D),
    .Q(Q_d32));
  always @(posedge CLK) begin
    if((rst == 1'b1)) begin
      Q <= 1'b0;
    end else begin
      if((srst == 1'b1)) begin
        Q <= 1'b0;
      end else begin
        case((DELAY))
          6'b000000 : Q <= D;
          6'b000001 : Q <= Q_d1;
          6'b000010 : Q <= Q_d2;
          6'b000100 : Q <= Q_d4;
          6'b001000 : Q <= Q_d8;
          6'b010000 : Q <= Q_d16;
          6'b100000 : Q <= Q_d32;
          default : Q <= D;
        endcase
      end
    end
  end
endmodule

