module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 32;
    parameter lpm_size = 1;
    parameter lpm_type = "lpm_or";

    reg [lpm_width-1:0] result;

    initial begin
        if (lpm_width <= 0) $fatal(1, "lpm_width must be greater than zero");
        if (lpm_size <= 0) $fatal(1, "lpm_size must be greater than zero");
    end

    always @(*) begin
        result = 0;
        for (int i = 0; i < lpm_size; i = i + 1) begin
            for (int j = 0; j < lpm_width; j = j + 1) begin
                result[j] = result[j] | data[(i * lpm_width) + j];
            end
        end
    end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [15:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if (cnt == (NUM_DIV - 1)) begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

