module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] upper_bound = 32'd100000000;
reg [27:0] counter = 0;
  always @(posedge clk) begin
    if(counter == upper_bound) begin
      counter <= 0;
      pulse <= 1;
    end
    else begin
      counter <= counter + 1;
      pulse <= 0;
    end
  end
endmodule

