OV0_TDATA <= IV_TDATA;
OV0_TLAST <= IV_TLAST;
OV0_TKEEP <= IV_TKEEP;
OV0_TUSER <= IV_TUSER;
OV0_TID <= IV_TID;
OV1_TDATA <= IV_TDATA;
