	output [31:0]	data1, data2;
	input regwrite;
	input [4:0]wrreg;
	input [31:0]wrdata;
reg [31:0]registers[0:31];
	always @(posedge clk or negedge rst) begin
		if(!rst) begin
			for(int i=0;i<32;i=i+1) begin
				registers[i] <= 32'b0;
			end
		end
		else if(regwrite) begin
