				registers[wrreg] <= wrdata;
			end
			else begin
				registers[wrreg] <= 32'b0;
			end
		end
	end
	assign data1 = of_control[1] ? registers[read1] : 32'b0;
	assign data2 = of_control[1] ? registers[read2] : 32'b0;
endmodule

