module lfsr    (
out             ,  
enable          ,  
clk             ,  
reset              
);


output [7:0] out;

input enable, clk, reset;
wire linear_feedback;

reg [7:0] out;

assign linear_feedback = ~ (out[7] ^ out[3]);

always @(posedge clk)
begin
    if (reset)
        out <= 8'b00000000;
    else if (enable)
        out <= {out[6:0], linear_feedback};
end

endmodule

module submod (a, b, c);

   input a, b;
   output c;
subsub s1 (a, b, c1);
   subsub s2 (a, b, c2);
   assign c = c1 ^ c2;
endmodule

module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
parameter Baud = 115200;
parameter Oversampling = 100000000 / Baud;
parameter log2 = $clog2(Oversampling);

reg [log2:0] Acc;
wire [log2:0] Inc = Oversampling / 2 ** log2;

always @(posedge clk) begin
	if (enable) begin
		Acc <= Acc + Inc;
	end else begin
		Acc <= 0;
	end
end

assign tick = Acc == 0;

endmodule

module f9_NegEdgeClock(q, d, clk, reset);
input d, clk, reset;
output reg q;
always @(negedge clk, negedge reset) begin
    if (reset)
      q <= 1'b0;
    else
      q <= d;
  end
endmodule

module submuladd_2_stage_unsigned_8_bit(
	input  [7:0] a,
	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);
logic  [15:0] stage0;
	logic  [15:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) + c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

