module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = q_reg == maxbit-1;
    assign q_reset = q_reg == 0;
    assign f1 = button_in & ~f2;
    assign f2 = ~button_in & f1;
    always @(posedge clk) begin
        if (n_reset == 0) begin
            q_reg <= 0;
            out <= 0;
        end else begin
            q_reg <= q_next;
            out <= q_reg == maxbit-1;
        end
    end
    always @(posedge clk) begin
        if (n_reset == 0) begin
            q_next <= 0;
        end else begin
            q_next <= q_add ? q_reg + 1 : q_reg;
        end
    end
endmodule

