module timer_variable(
input wire zedboard_clk,
input wire enable,
input wire reset,
output reg timerOutput
); 

reg [31:0] timer_value;
  always @(posedge zedboard_clk) begin
    if(reset == 1'b1) begin
      timer_value <= 0;
    end
    else if(timer_value == 100000) begin
      timer_value <= 0;
      timerOutput <= 1'b1;
    end
    else begin
      timer_value <= timer_value + 1;
      timerOutput <= 1'b0;
    end
  end
endmodule

