  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_prev <= 1'b0;
      rise <= 1'b0;
      down <= 1'b0;
    end else begin
      if (a != a_prev) begin
        if (a) begin
          rise <= 1'b1;
          a_prev <= a;
        end else begin
          down <= 1'b1;
          a_prev <= a;
        end
      end
    end
  end
