module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

wire [31:0] x_0;
wire [31:0] x_i;
wire [31:0] x_i_mux;
wire [31:0] x_next;
wire [31:0] sqrt;
wire val_comb;
wire z_comb;
wire val_ff;
wire z_ff;
  assign x_0 = 32'h1;
  assign x_i_mux = SEL ? x_i : x_0;
  assign x_next = x_i_mux + (n / x_i_mux);
  assign sqrt = x_i_mux;
  assign VAL = val_ff;
  assign Z = z_ff;
  assign out_sqrt = sqrt;
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        val_ff <= val_comb;
        z_ff <= z_comb;
      end
    end
  end
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      val_comb <= 1'b0;
      z_comb <= 1'b0;
    end else begin
      if((n == 32'h0)) begin
        val_comb <= 1'b0;
        z_comb <= 1'b1;
      end else begin
        if((x_next >= x_i)) begin
          val_comb <= 1'b1;
          z_comb <= 1'b0;
        end
        else begin
          val_comb <= 1'b0;
          z_comb <= 1'b0;
        end
      end
    end
  end
  reg [31:0] out_sqrt_reg;
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      out_sqrt_reg <= 32'h0;
    end else begin
      if((EN == 1'b1)) begin
        out_sqrt_reg <= sqrt;
      end
    end
  end
  assign out_sqrt = out_sqrt_reg;
endmodule

