module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n=30; 
parameter count=4; 
reg [1:0]delay; 
reg [31:0]counter; 
reg [7:0]s_in; 
top top1(clk,reset,rxD,s_in);
always@(posedge clk)
begin
if(reset==1)
begin
sout<=0;
signal<=0;
counter<=0;
end
else
begin
if(counter==count)
begin
signal<=1;
counter<=0;
end
else
begin
sout<=s_in;
counter<=counter+1;
end
end
end
endmodule

