module twocmp(input [31:0]A,output [31:0]B);
genvar i;
generate
for(i=0;i<32;i=i+1)
begin:bit
if(i==0)
begin
B[i]=A[i];
end
else
begin
if(A[0:i-1] | 1'b0)
begin
B[i]=~A[i];
end
else
begin
B[i]=A[i];
end
end
end
endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock) begin
    if (reset) begin
        gnt_0 <= 0;
        gnt_1 <= 0;
    end
    else begin
        if (req_0 && req_1) begin
            gnt_0 <= 1;
            gnt_1 <= 0;
        end
        else if (req_0) begin
            gnt_0 <= 1;
            gnt_1 <= 0;
        end
        else if (req_1) begin
            gnt_0 <= 0;
            gnt_1 <= 1;
        end
        else begin
            gnt_0 <= 0;
            gnt_1 <= 0;
        end
    end
end

endmodule

