module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
wire [numOfCounters-1:0] counts;
wire [numOfCounters-1:0] terminalCounts;
wire [numOfCounters-1:0] enable;

assign outCount = counts[numOfCounters-1];

generate
   genvar i;
   for (i = 0; i < numOfCounters; i = i + 1) begin : counterChain
      NBitCounter #(
         .counterSize(counterSize)
      ) counter (
         .clk(clk),
         .reset(reset),
         .count(counts[i]),
         .terminalCount(terminalCounts[i]),
         .enable(enable[i])
      );
      if (i != 0) begin
         assign enable[i] = terminalCounts[i-1];
      end
   end
endgenerate

endmodule

