module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] H_ACTIVE = 640;
parameter [31:0] H_SYNC = 96;
parameter [31:0] H_BACK = 48;
parameter [31:0] H_RETRACE = 48;
parameter [31:0] V_ACTIVE = 480;
parameter [31:0] V_SYNC = 2;
parameter [31:0] V_BACK = 33;
parameter [31:0] V_RETRACE = 2;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
always @(posedge clk) begin
  if(rst == 1'b1) begin
    h_count_reg <= 10'd0;
    v_count_reg <= 10'd0;
  end else begin
    if(h_count_reg == H_ACTIVE - 10'd1) begin
      h_count_reg <= 10'd0;
    end else begin
      h_count_reg <= h_count_reg + 10'd1;
    end
    if(v_count_reg == V_ACTIVE - 10'd1) begin
      v_count_reg <= 10'd0;
    end else begin
      v_count_reg <= v_count_reg + 10'd1;
    end
  end
end
assign xaddr = h_count_reg;
assign yaddr = v_count_reg;
assign active = (h_count_reg < H_ACTIVE) & (v_count_reg < V_ACTIVE);
assign hsync = (h_count_reg < H_ACTIVE) & (h_count_reg >= H_ACTIVE - H_SYNC) & (h_count_reg < H_ACTIVE - H_SYNC - H_BACK) & (h_count_reg < H_ACTIVE - H_SYNC - H_BACK - H_RETRACE);
assign vsync = (v_count_reg < V_ACTIVE) & (v_count_reg >= V_ACTIVE - V_SYNC) & (v_count_reg < V_ACTIVE - V_SYNC - V_BACK) & (v_count_reg < V_ACTIVE - V_SYNC - V_BACK - V_RETRACE);
endmodule

module slink_demet_reset
  (
   input  wire   clk,
   input  wire   reset,
   input  wire   sig_in,
   output wire   sig_out
  );
reg [1:0] demet_flops;

  always @(posedge clk or posedge reset)
    begin
      if (reset)
        demet_flops <= 2'b00;
      else
        demet_flops <= {demet_flops[0], sig_in};
    end

  assign sig_out = demet_flops[0];

endmodule

