    pedge[0] <= in[0] & ~in[1];
    pedge[1] <= in[1] & ~in[2];
    pedge[2] <= in[2] & ~in[3];
    pedge[3] <= in[3] & ~in[4];
    pedge[4] <= in[4] & ~in[5];
    pedge[5] <= in[5] & ~in[6];
    pedge[6] <= in[6] & ~in[7];
    pedge[7] <= in[7] & ~in[8];
end
endmodule

