module TopModule(
    input  clk,
    input  shift_ena,
    input  count_ena,
    input  data,
    output reg [3:0] q
    );
always @(posedge clk) begin
    if (shift_ena) begin
        q[3] <= q[2];
        q[2] <= q[1];
        q[1] <= q[0];
        q[0] <= data;
    end
    else if (count_ena) begin
        q[3] <= q[2];
        q[2] <= q[1];
        q[1] <= q[0];
        q[0] <= q[0] - 1;
    end
end
endmodule

