module TopModule(
    input  clk,
    input  reset,
    output shift_ena
);
wire [3:0] shift_ena_reg;
reg [3:0] shift_ena_reg_next;

always @(posedge clk) begin
    if (reset) begin
        shift_ena_reg <= 4'b0000;
    end else begin
        shift_ena_reg <= shift_ena_reg_next;
    end
end

assign shift_ena = shift_ena_reg[0];

always @(*) begin
    shift_ena_reg_next = shift_ena_reg;
    if (reset) begin
        shift_ena_reg_next = 4'b1111;
    end else begin
        if (shift_ena_reg == 4'b1111) begin
            shift_ena_reg_next = 4'b0000;
        end else begin
            shift_ena_reg_next = shift_ena_reg + 1;
        end
    end
end

endmodule

