    output q[99:0]
);
reg [99:0] rotator;

always @(posedge clk) begin
    if (load) begin
        rotator <= data;
    end else begin
        case (ena)
            2'b01: rotator <= {rotator[98:0], rotator[99]};
            2'b10: rotator <= {rotator[0], rotator[99:1]};
            default: rotator <= rotator;
        endcase
    end
end

assign q = rotator;

endmodule

