module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  predict_taken,
    input  train_mispredicted,
    input  train_taken,
    input  train_history   (32 bits),
    output predict_history (32 bits)
);
reg [31:0] history;

always @(posedge clk) begin
    if (areset) begin
        history <= 0;
    end else if (predict_valid) begin
        history[0] <= predict_taken;
        history[31:1] <= history[30:0];
    end else if (train_mispredicted) begin
        history <= train_history;
        history[31] <= train_taken;
    end
end

assign predict_history = history;

endmodule

module TopModule(
    input  clk,
    input  reset,
    input  in,
    output out
);
reg [3:0] state;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= 4'b0000;
        end else begin
            case (state)
                4'b0000: state <= in ? 4'b0001 : 4'b0000;
                4'b0001: state <= in ? 4'b0010 : 4'b0001;
                4'b0010: state <= in ? 4'b0011 : 4'b0010;
                4'b0011: state <= in ? 4'b0100 : 4'b0011;
                default: state <= 4'b0000;
            endcase
        end
    end
    assign out = state[3];
endmodule

module TopModule(
    input  clk,
    input  reset,
    input  x,
    output z
);
reg [2:0] y;
assign z = y[2];
always @(posedge clk) begin
    if (reset) begin
        y <= 3'b000;
    end else begin
        case ({y[2], y[1], y[0], x})
            3'b000: y <= {y[2], y[1], y[0], 1'b0};
