                    if (y == 1'b1) begin
                        state <= 2'b11;
                    end
                    else begin
                        g <= 1'b0;
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end
    assign f = f;
    assign g = g;
endmodule

