    if (reset) begin
        out_byte <= 8'b0;
        done <= 1'b0;
    end else begin
        if (in == 1'b0) begin
            out_byte <= 8'b0;
            done <= 1'b0;
        end else if (in == 1'b1) begin
            out_byte <= out_byte << 1;
            out_byte[7] <= in;
            if (out_byte == 8'b10000000 && in == 1'b1) begin
                done <= 1'b1;
            end
        end
    end
end
endmodule

