  input k,
  output reg Q
);
reg Qold;

  always @(posedge clk) begin
    Qold <= Q;
    if (j == 1'b0 && k == 1'b0) begin
      Q <= Qold;
    end
    else if (j == 1'b0 && k == 1'b1) begin
      Q <= 1'b0;
    end
