module TopModule (
  input clk,
  input areset,
  input x,
  output z
);
reg q;
  reg qbar;
  reg q_next;
  reg qbar_next;
  reg z_next;
  reg z;
  reg x_next;
  reg areset_next;
  assign z = z_next;
  assign x = x_next;
  assign areset = areset_next;
  always @(posedge clk) begin
    q_next = q;
    qbar_next = qbar;
    z_next = z;
    x_next = x;
    areset_next = areset;
    if (areset == 1'b0) begin
      q_next = 1'b0;
      qbar_next = 1'b1;
      z_next = 1'b0;
      x_next = 1'b0;
      areset_next = 1'b0;
    end else begin
      q_next = q;
      qbar_next = qbar;
      z_next = z;
      x_next = x;
      areset_next = areset;
      if (q == 1'b0) begin
        q_next = 1'b1;
        qbar_next = 1'b0;
        z_next = 1'b0;
        x_next = x;
        areset_next = 1'b0;
      end else if (q == 1'b1) begin
        q_next = 1'b0;
        qbar_next = 1'b1;
        z_next = 1'b1;
        x_next = x;
        areset_next = 1'b0;
      end else if (q == 1'b0 && qbar == 1'b1) begin
        q_next = 1'b0;
        qbar_next = 1'b1;
        z_next = 1'b1;
        x_next = x;
        areset_next = 1'b0;
      end else if (q == 1'b1 && qbar == 1'b0) begin
        q_next = 1'b1;
        qbar_next = 1'b0;
        z_next = 1'b0;
        x_next = x;
        areset_next = 1'b0;
      end else if (q == 1'b0 && qbar == 1'b0) begin
        q_next = 1'b0;
        qbar_next = 1'b1;
        z_next = 1'b1;
        x_next = x;
        areset_next = 1'b0;
      end else if (q == 1'b1 && qbar == 1'b1) begin
        q_next = 1'b1;
        qbar_next = 1'b0;
        z_next = 1'b0;
        x_next = x;
        areset_next = 1'b0;
      end
    end
  end
endmodule

